-- ----------------------------
-- Table structure for knowledge_doc
-- ----------------------------
DROP TABLE IF EXISTS `knowledge_doc`;
CREATE TABLE `knowledge_doc`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '知识标题',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类：法规标准/种植标准/储存保鲜/检测知识/流通标准/消费科普',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '知识正文（喂给大模型的片段）',
  `embedding` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '向量（JSON 数组，text-embedding-v3 生成，应用自动回写）',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_knowledge_category`(`category` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '农事知识库（AI RAG 检索）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of knowledge_doc
-- ----------------------------
INSERT INTO `knowledge_doc` VALUES (1, 'GB2763 叶菜类蔬菜农残限量常识', '法规标准', '根据国家标准 GB 2763《食品中农药最大残留限量》，叶菜类蔬菜（如小白菜、生菜、油麦菜）对常见杀虫剂的限量要求严格：毒死蜱最大残留限量 0.1 mg/kg，氯氰菊酯 2 mg/kg，吡虫啉 1 mg/kg。检测报告结果低于该限值即判定为合格。', '[-0.059155210852622986,-0.0036972006782889366,-0.027650726959109306,-0.054916076362133026,-0.010453322902321815,-0.10150802880525589,0.01206226833164692,0.10790527611970901,-0.053451646119356155,0.02422088012099266,-0.04643780365586281,0.04061862826347351,0.010077581740915775,0.030078595504164696,0.031620100140571594,-0.04404847323894501,-0.04034886509180069,-0.042622581124305725,-0.01009685080498457,-0.05456923693418503,-0.042314283549785614,-0.0029481262899935246,-0.033836010843515396,-0.00910450704395771,0.03194766864180565,6.774187204428017E-4,-0.016195425763726234,-0.0018606433877721429,0.007750874385237694,0.008261497132480145,0.03181278705596924,-0.0331423357129097,0.02880685403943062,0.0032732870895415545,-0.016995079815387726,5.425371346063912E-4,0.030560314655303955,-0.06300897151231766,-0.05900106206536293,0.025242125615477562,0.00859870109707117,-0.03907712548971176,-0.022467419505119324,-0.010453322902321815,-0.0026831801515072584,-0.02770853228867054,-7.647304446436465E-4,-0.048326145857572556,-0.00580954272300005,-0.0015704070683568716,-0.01984686218202114,0.004121114499866962,0.07164139300584793,-0.0843973383307457,0.04416408762335777,0.07283605635166168,0.043547485023736954,-0.007360680960118771,0.00881547573953867,0.006652552634477615,-0.011773236095905304,-0.01794888637959957,0.0090129803866148,-0.009383904747664928,0.009730743244290352,0.022351806983351707,0.015810050070285797,-0.03425992280244827,-0.012322396971285343,-0.01873890683054924,-0.023700622841715813,0.028363671153783798,0.056187815964221954,-0.021773742511868477,-0.05745955929160118,-0.037497080862522125,-0.0025266213342547417,-0.0027554382104426622,0.05665026977658272,0.05984888970851898,0.096343994140625,-0.012640331871807575,-0.019634906202554703,-0.0025290297344326973,0.00366829754784703