INSERT INTO `knowledge_doc` VALUES (10, '施肥与农家肥安全使用', '种植标准', '种植过程中农家肥（鸡粪、牛粪等）必须充分腐熟后使用，未腐熟农家肥携带大肠杆菌等病原菌并可能污染土壤。化肥应按测土配方施肥，采收前 15 天停止追施速效氮肥，避免硝酸盐积累超标。有机认证地块禁止使用化学合成氮肥。', '[-0.02398783341050148,0.046888839453458786,-0.028684480115771294,-5.173346726223826E-4,-0.030489390715956688,-0.0766601487994194,0.022241147235035896,0.09168165177106857,-0.09090534597635269,0.010334564372897148,-0.02503584511578083,0.04727699235081673,0.012323846109211445,-0.019834600389003754,0.02150365710258484,-0.0348949208855629,-0.04987761378288269,-0.011663987301290035,-0.010567455552518368,0.009742631576955318,-0.051546670496463776,-0.013323339633643627,-0.008946917951107025,0.012741110287606716,0.06625765562057495,0.027869360521435738,-0.010043449699878693,-0.017350422218441963,-0.012799333781003952,-0.019427040591835976,-0.01937852054834366,-0.010499528609216213,-0.032682452350854874,0.002170015824958682,-0.06350177526473999,-0.011925989761948586,-0.014478093944489956,-0.028102250769734383,-0.053526248782873154,0.04219219088554382,0.0029839235357940197,-0.010771235451102257,-0.02804402820765972,-0.016661452129483223,0.04704409837722778,-0.0018728364957496524,-0.02280396781861782,-0.031420957297086716,-0.0052788760513067245,0.0014458686346188188,0.013449489139020443,-0.008253095671534538,0.030101237818598747,-0.0823659896850586,0.04428821802139282,0.017476573586463928,0.05387558788061142,-0.007971684448421001,0.013682380318641663,0.020222753286361694,-0.027054239064455032,-0.014701281674206257,-0.031750887632369995,-0.014303424395620823,-0.009257440455257893,0.02779172919690609,0.004439495969563723,-0.002518140245229006,-0.05333217233419418,-0.037204429507255554,0.010829458944499493,0.009267143905162811,0.011266130022704601,-0.004531682003289461,-0.042580343782901764,-0.0621432363986969,0.07033325731754303,-0.029266709461808205,0.03446795418858528,0.04098891839385033,0.0663352832198143,-0.008762545883655548,0.04661713168025017,0.01825287751853466,0.024997029453516006,-0.03101339563727379,