INSERT INTO `knowledge_doc` VALUES (25, '生物农药与化学农药区别', '法规标准', '生物农药源于生物活体或其代谢产物，如苏云金杆菌（Bt）、枯草芽孢杆菌、苦参碱、印楝素，通常低毒易降解、安全间隔期短；化学合成农药见效快但需严格执行安全间隔期。绿色种植优先选用生物农药，溯源农事记录中登记用药类型可帮消费者判断种植规范程度。', '[-0.049355510622262955,0.013331436552107334,-0.052313726395368576,-0.046397291123867035,-0.05196341127157211,-0.11155590415000916,-0.005536925047636032,0.1096097081899643,-0.004087009932845831,0.02565085142850876,-0.05943680182099342,-0.0013282782165333629,0.009614204056560993,5.613556713797152E-4,-0.025261612609028816,-0.005274188704788685,-0.10244771093130112,-0.03446711599826813,0.004602751694619656,-0.0011780562344938517,-0.02712996117770672,-0.024366363883018494,-7.423670467687771E-5,0.0016226401785388589,0.07216491550207138,0.037795111536979675,-0.014868930913507938,-0.014460230246186256,-0.0053471713326871395,0.01379852369427681,-0.0030482280999422073,-0.027071574702858925,-0.043867237865924835,-0.005400691647082567,-0.0495501272380352,-0.01128793228417635,-0.011803673580288887,-0.029854632914066315,-0.04958905279636383,0.01670808531343937,0.04094794765114784,-0.0030944503378123045,0.012698923237621784,-0.024677755311131477,0.019724687561392784,-0.028881536796689034,0.004191617947071791,-0.030652573332190514,-0.026234710589051247,-0.021953081712126732,-0.0042937928810715675,0.0037342619616538286,0.06212254986166954,-0.07438357919454575,0.027207808569073677,0.008572990074753761,-0.0016968388808891177,-0.02004580944776535,0.04865488037467003,-0.0011172376107424498,-0.00641271285712719,-0.005483404733240604,0.015170590952038765,-0.004537067376077175,-0.019987424835562706,0.006033204961568117,-0.029231851920485497,-0.04063655436038971,-0.025339460000395775,-0.026448791846632957,-0.05651750788092613,0.004308389499783516,0.01092788577079773,-0.0022429898381233215,-0.007230115123093128,-0.05546656250953674,-0.0012127228546887636,-0.06181115657091141,0.009799093008041382,0.020707515999674797,0.04429540038108826,-0.033143702894449234,0.034116800874471664,0.021836308762431145,0.0030749