INSERT INTO `knowledge_doc` VALUES (26, '农药残留快速检测技术', '法规标准', '酶抑制率快速检测法（速测卡/速测仪）可在 15-30 分钟内筛查有机磷和氨基甲酸酯类农残，抑制率≥50% 判为阳性需复检。快检是市场准入初筛手段，法定仲裁以实验室色谱-质谱法为准。快检阳性但实验室复检合格的批次以实验室结论为准。', '[-0.032644160091876984,-0.01586734503507614,-0.02867732383310795,-0.029760947450995445,-0.042416125535964966,-0.03500491380691528,0.02289154939353466,0.14172248542308807,-0.03510166332125664,0.04055848345160484,-0.06006370857357979,0.013864576816558838,0.035624124109745026,0.05569051206111908,0.03198624774813652,-0.018218422308564186,-0.033631034195423126,-0.04315143823623657,0.008248116821050644,-0.05104641243815422,-0.015490012243390083,0.03570152819156647,0.015509363263845444,-0.00864963885396719,0.06985501945018768,0.03463725373148918,-0.053832873702049255,-1.6266448074020445E-4,0.06811348348855972,-0.0047722975723445415,0.00989290326833725,-0.035566072911024094,0.017995892092585564,-0.03334077447652817,-0.05514870211482048,0.027109939604997635,0.0012529398081824183,-0.06486261636018753,-0.055574409663677216,0.02960614487528801,0.014348337426781654,-0.04783424362540245,-0.0027646913658827543,-0.02291089855134487,0.013119585812091827,-0.007706305477768183,0.023781668394804,-0.057935163378715515,1.2985947250854224E-4,0.0287740770727396,0.021304814144968987,0.0036185288336127996,0.01804426871240139,-0.07906582206487656,-0.0038120329845696688,0.007648254279047251,0.011049090884625912,-0.002135802758857608,-0.010710458271205425,-0.020066387951374054,0.019795481115579605,0.03156053647398949,-0.023936470970511436,0.012422970496118069,0.018905362114310265,0.014474115334451199,0.0029146571177989244,-0.008402920328080654,-0.028851479291915894,-0.0287740770727396,-0.015944747254252434,-0.010507279075682163,0.03022535890340805,-0.015751242637634277,-0.06648804992437363,-0.008417433127760887,0.03726891055703163,-0.03165728971362114,0.07500223070383072,-0.0025300676934421062,0.07213836908340454,-0.02614242024719715,-0.010110595263540745,0.03401803970336914,0.00644369050860405,0.020066387951374054,0