INSERT INTO `knowledge_doc` VALUES (29, '番茄灰霉病识别与防治', '种植标准', '番茄灰霉病在低温高湿（15-23 度、湿度 90% 以上）易发，表现为叶片出现 V 形褐斑、果实蒂部生灰色霉层。防治：及时摘除病果病叶带出棚外销毁、控制浇水加强通风、发病初期喷施腐霉利或嘧霉胺，注意轮换用药防抗性，安全间隔期按标签执行。', '[-0.04106752574443817,-0.01301380805671215,-0.07784906774759293,-0.006127010099589825,0.003713708370923996,-0.0707966759800911,-0.043444301933050156,0.11260450631380081,-0.013043031096458435,0.01837128959596157,-0.008328448049724102,0.048314739018678665,0.010968225076794624,0.02133251540362835,0.0962398424744606,-0.0039060907438397408,-0.054120298475027084,-0.010510403662919998,-0.01820569485425949,-0.01788424514234066,0.0139976367354393,-0.01651078276336193,-0.03970380499958992,-0.022930018603801727,-0.06206885352730751,0.019559675827622414,-0.03643086925148964,-0.06277019530534744,0.02707963064312935,-0.0028078071773052216,0.029573295265436172,-0.03446321561932564,0.039236243814229965,-0.008372281678020954,-0.011542935855686665,0.042742956429719925,-0.010724702849984169,-0.030878571793437004,-0.04562625661492348,0.005113959312438965,0.028073200955986977,0.005708152428269386,0.018069321289658546,-0.011202005669474602,0.013072253204882145,-0.04999016597867012,-0.031151317059993744,-0.019394081085920334,-0.03346964344382286,-0.02318328060209751,-0.009351239539682865,-0.01690041646361351,0.00878139864653349,-0.06058824062347412,0.06487422436475754,0.02363136224448681,0.07847248762845993,-0.06152336299419403,0.0038086818531155586,-0.006200066767632961,-0.054665789008140564,-0.024585967883467674,0.0069598546251654625,-0.01630622334778309,0.0027152688708156347,0.07013429701328278,0.00788036733865738,0.004176400136202574,-0.006628665141761303,-0.054276153445243835,0.023007946088910103,0.028365425765514374,0.01131889596581459,-0.046600341796875,-0.038418009877204895,-0.05528920516371727,0.04079478234052658,-0.0040497686713933945,0.004753546789288521,0.041807834059000015,0.050613582134246826,-0.040171366184949875,-0.01908237300813198,0.001141508691944182,0.003299721283838153,-0.02859920822083