INSERT INTO `knowledge_doc` VALUES (30, '黄瓜霜霉病识别与防治', '种植标准', '黄瓜霜霉病典型症状是叶片正面出现多角形黄褐斑、背面生灰黑色霉层，高湿通风差时迅速蔓延。预防为主：选用抗病品种、地膜覆盖降低棚内湿度、发病前用代森锰锌保护性喷施，发病后用烯酰吗啉或霜脲氰治疗，每 7 天一次连续 2-3 次。', '[-0.032030098140239716,0.03722779452800751,-0.03741959482431412,-0.026621421799063683,-0.039893776178359985,-0.0535113625228405,-0.015305399894714355,0.14231336116790771,-0.03226025402545929,0.0111146355047822,-0.03158896416425705,0.04737385734915733,-0.04112127423286438,0.042885806411504745,0.03680584207177162,0.013416199944913387,-0.051248155534267426,-0.033180881291627884,0.007662289775907993,0.010989967733621597,-2.2101607100921683E-5,0.00977685209363699,-0.08024786412715912,-0.010500885546207428,-0.03559752181172371,-2.956370881292969E-4,-0.03857037425041199,-0.017319267615675926,0.021826498210430145,0.004778142552822828,0.010011803358793259,-0.04369135573506355,0.028309235349297523,-0.001472041942179203,-8.96051584277302E-4,0.014586160890758038,-0.003078341716900468,-0.018613897264003754,-0.04530245065689087,0.010155650787055492,0.02305399812757969,0.058920037001371384,-0.008300014771521091,0.01923723891377449,0.03795662522315979,-0.008184936828911304,0.010213189758360386,-0.007101283874362707,0.04131307080388069,0.009743287228047848,-0.024665093049407005,-0.04092947766184807,0.028366774320602417,-0.06728238612413406,0.003581808879971504,-0.03229861333966255,0.05266745388507843,-0.03730451688170433,0.03578931838274002,-0.013684715144336224,-0.0645972266793251,0.0037064768839627504,-0.014010770246386528,-0.020100325345993042,-0.012438034638762474,0.0725376233458519,0.03026556596159935,-0.02407052181661129,-0.021615521982312202,-0.04752729460597038,0.0060703749768435955,0.005509368609637022,0.021270286291837692,-0.041389789432287216,-0.06778105348348618,-0.05401003360748291,-0.006516302935779095,-0.006290941499173641,0.09666568785905838,0.024876069277524948,0.02859693206846714,-0.01120094396173954,-0.020272942259907722,-0.0017381602665409446,0.01791383884847164,0.026046032086014748,0.015