INSERT INTO `knowledge_doc` VALUES (31, '白粉病综合防治', '种植标准', '白粉病在黄瓜、南瓜、草莓上高发，叶面出现白色粉状霉斑。防治要点：合理密植增强通风透光、避免偏施氮肥、发病初期喷施醚菌酯或氟菌唑，生物防治可用枯草芽孢杆菌。棚室可高温闷棚（36-40 度保持 2 小时）抑制病菌，注意闷棚前一日浇足水防烧苗。', '[-0.04096880555152893,0.02046511322259903,-0.040891651064157486,-0.050034407526254654,-0.018295155838131905,-0.06797272711992264,0.004776318557560444,0.13440236449241638,-0.04494223743677139,0.03234683722257614,-0.04791266843676567,0.07267912477254868,0.006635249126702547,0.04235757887363434,0.025075068697333336,-0.048799943178892136,-0.0764210969209671,-0.02189246378839016,-0.018131203949451447,0.005637068301439285,0.02760186418890953,-0.0015792471822351217,-0.05026586726307869,-0.00241829757578671,0.023609140887856483,-0.010116825811564922,-0.012605044059455395,-0.025904474779963493,0.0019360845908522606,-0.034719325602054596,-0.009991450235247612,-0.050844524055719376,0.010193980298936367,-0.07329635322093964,-0.008043310604989529,-0.047372590750455856,-0.02424566261470318,-0.023551275953650475,-0.04729543626308441,-0.011245204135775566,0.03361988067626953,0.02453499101102352,0.005858886055648327,0.03965718671679497,-0.023802027106285095,-0.028701309114694595,0.007213904522359371,0.00910900067538023,-0.02756328694522381,0.00557438051328063,-0.013781643472611904,-0.03934856876730919,0.033909209072589874,-0.08810993283987045,-0.032173242419958115,0.023030485957860947,0.058714237064123154,0.03585734963417053,0.03699536994099617,-0.02505578100681305,-0.02846984751522541,0.011042675003409386,-0.0081879748031497,-0.009697300381958485,0.004590666387230158,0.08841855078935623,-0.020233651623129845,0.004814895335584879,-0.015980534255504608,-0.08533238619565964,-0.00839532632380724,0.007049952168017626,0.0403129942715168,-0.05281195417046547,-0.06612102687358856,-0.04949432983994484,0.014427809044718742,-0.004679875914007425,0.04849132522940636,0.044209275394678116,0.053544916212558746,-0.04077592119574547,-0.022644715383648872,0.029318541288375854,0.03934856876730919,0.016134843230247498,0.0