INSERT INTO `knowledge_doc` VALUES (32, '番茄早疫晚疫病区别与防治', '种植标准', '早疫病叶面出现同心轮纹状褐斑（靶斑），高温高湿发病；晚疫病叶缘生水浸状绿褐斑、背面有白色霉层，低温高湿（15-22 度）流行速度快，可数日内毁棚。晚疫病须立即喷施氟菌霜霉威或烯酰吗啉并清除病株，早疫病用苯醚甲环唑或代森锰锌防治。', '[-0.013209023512899876,-0.012997524812817574,-0.06352636218070984,-0.015708547085523605,-0.03851189836859703,-0.05341290682554245,-0.021342089399695396,0.1191311627626419,-0.012314962223172188,0.014468398876488209,-0.012026555836200714,0.05118256062269211,-0.006811202969402075,0.041722822934389114,0.031936224550008774,0.00836859829723835,-0.031974680721759796,-0.020976774394512177,-0.02222653664648533,-0.022784123197197914,0.018669521436095238,-0.0039031028281897306,-0.032570719718933105,-2.8953319997526705E-5,-0.003605082631111145,0.026744907721877098,-0.005114410538226366,-0.02332248166203499,0.04226118326187134,0.02295716665685177,-0.012843707576394081,0.003391181118786335,0.055181797593832016,-0.01916942559182644,-0.008464734070003033,0.032320767641067505,-0.017150580883026123,-0.030859507620334625,-0.0503365695476532,-0.022514943033456802,0.013641633093357086,0.019505901262164116,0.023187892511487007,0.0030499000567942858,0.008695459924638271,-0.049682848155498505,-0.014285741373896599,-0.04756786301732063,-0.021322863176465034,-0.06148828938603401,-0.01368970051407814,0.00593156274408102,0.02589891478419304,-0.054566532373428345,0.09828897565603256,0.007835046388208866,0.0789080485701561,-0.07048657536506653,0.025937369093298912,0.017765847966074944,-0.04802931472659111,-0.022418808192014694,0.009113648906350136,-0.025725869461894035,0.006378592923283577,0.05868113413453102,-0.004950980190187693,-1.8566176004242152E-4,-0.011478583328425884,-0.03262840211391449,0.026475727558135986,0.01649685762822628,0.03491642698645592,-0.05122101679444313,-0.04030001908540726,-0.06075765937566757,0.01746782660484314,-0.03789662942290306,0.04268417879939079,0.022937940433621407,0.05314372479915619,-0.0162372924387455,0.002557205269113183,-0.009825051762163639,0.011776603758335114,-0.0105460686609