INSERT INTO `knowledge_doc` VALUES (35, '菜青虫与斜纹夜蛾防治', '种植标准', '菜青虫（菜粉蝶幼虫）啃食甘蓝白菜叶片成孔洞，斜纹夜蛾幼虫群集暴食且昼伏夜出。首选生物农药苏云金杆菌（Bt）或甲维盐，傍晚施药效果好（夜蛾类夜间取食）；成虫期可用性诱剂或杀虫灯诱杀，卵期释放赤眼蜂。收获前 5-7 天停止用药。', '[-0.03478432819247246,0.05755401402711868,-0.050732798874378204,-0.06398765742778778,-0.034861840307712555,-0.034454893320798874,-0.0049560400657355785,0.12642504274845123,-0.06015072762966156,0.022285224869847298,-0.060499537736177444,0.03259456157684326,-0.03960956260561943,0.011413910426199436,-0.01218904834240675,-0.04724467545747757,-0.03276896849274635,-0.03129620477557182,0.014407881535589695,-0.06708821654319763,-0.012605685740709305,0.010319028049707413,-0.07305677980184555,-0.032517049461603165,-0.014669490978121758,0.006695256568491459,0.012741334736347198,-0.044802989810705185,0.006516005843877792,0.01450477447360754,0.020599298179149628,-0.02945525199174881,0.007838585413992405,-0.057282716035842896,-0.054724760353565216,2.638043588376604E-5,-0.009078806266188622,0.018913373351097107,-0.05441470444202423,0.013312999159097672,0.02412617765367031,-0.012460347265005112,0.0021812873892486095,-0.02284719981253147,0.012557239271700382,-0.04050097241997719,-0.011036030948162079,-0.02307973988354206,0.011307328939437866,0.022285224869847298,-0.028021246194839478,-0.0036673727445304394,0.031645018607378006,-0.07332807779312134,0.0380786657333374,0.00995083712041378,0.071894071996212,-0.05015144497156143,0.026509728282690048,-0.011375153437256813,-0.016461998224258423,-0.03131558373570442,-2.136171970050782E-4,-0.026005888357758522,-0.011065098457038403,0.08030431717634201,0.06526663899421692,0.01990167424082756,-0.012780091725289822,0.005808691959828138,-0.0023968727327883244,0.023835500702261925,0.07817269116640091,-0.025133857503533363,-0.06635183095932007,-0.040152158588171005,-0.019659442827105522,0.004360152408480644,0.0782502070069313,0.05363956466317177,0.05887174978852272,-0.00724754249677062,-0.05871672183275223,0.027246108278632164,0.018176991492509842,0.05146917700767517,0.02