INSERT INTO `knowledge_doc` VALUES (36, '潜叶蝇识别与防治', '种植标准', '潜叶蝇幼虫在叶片内蛀食形成蜿蜒白色隧道（鬼画符），影响光合作用与商品性。防治：摘除受害叶片集中处理、张挂黄板诱杀成虫、始见隧道时喷施灭蝇胺或阿维菌素，7 天一次连续 2 次。育苗期是防治关键窗口，带虫苗定植后虫害加重。', '[-0.05564035102725029,0.017986515536904335,-0.05482893064618111,-0.047719329595565796,-0.0017399684293195605,-0.04802844300866127,0.003221537685021758,0.10061629861593246,-0.009872298687696457,0.0494580902159214,-0.02666100114583969,0.010925214737653732,-0.013378799892961979,0.03357740491628647,0.03749927878379822,-0.09180658310651779,-0.03357740491628647,-0.02870887517929077,0.042657602578401566,-0.04891714081168175,0.0014332702849060297,-0.013707232661545277,-0.022893685847520828,-0.0035089163575321436,0.011408204212784767,0.06607291847467422,0.02602345682680607,-0.06479782611131668,-0.037248123437166214,-0.005626823753118515,0.012625336647033691,-0.051583241671323776,0.0035378956235945225,0.024477889761328697,-0.007776125334203243,-8.210815722122788E-4,0.03568324074149132,0.011350245214998722,-0.048839863389730453,0.04431908577680588,0.0033350400626659393,0.03995286300778389,0.028264526277780533,-0.02432333491742611,0.019020112231373787,-0.042541686445474625,0.01219064649194479,-0.016624486073851585,0.018624061718583107,-0.0075587802566587925,-0.027994051575660706,0.0076215690933167934,-0.02376306615769863,-0.07009138911962509,-0.007978981360793114,0.00596974603831768,0.03527752682566643,-0.028573637828230858,0.0340990349650383,-0.04806708171963692,0.0073510948568582535,0.007698846980929375,-0.010335967876017094,-0.004559417720884085,0.0030693961307406425,0.05289697274565697,0.04551689699292183,-0.004692239686846733,-0.03817546367645264,-0.07689187675714493,-0.009988215751945972,0.04686926677823067,0.021116286516189575,-0.042078014463186264,-0.051235489547252655,-4.102389211766422E-4,-0.06669114530086517,-0.008722783997654915,0.016962578520178795,0.03678445518016815,0.04474411532282829,-0.013668593019247055,-0.030254440382122993,0.043043993413448334,0.062440838664770126,0.021908387541770935,-