INSERT INTO `knowledge_doc` VALUES (38, '根结线虫危害与防控', '种植标准', '根结线虫侵染根系形成瘤状根结，植株矮化黄萎、结果少，重茬棚室危害重。防控：夏季高温闷棚（覆膜灌水 55 度以上 15 天）、轮作葱蒜类或种植万寿菊绿肥、定植前沟施淡紫拟青霉等生物菌剂，化学药剂可用噻唑膦颗粒剂严格按标签用量。', '[-0.011732169426977634,0.01695605181157589,-0.0612296536564827,-0.058085739612579346,-0.03684514760971069,-0.08956322818994522,-0.012038893066346645,0.11126390844583511,-0.04478161409497261,-0.0050609358586370945,-0.043171316385269165,0.03642340004444122,-0.026435721665620804,0.009637823328375816,0.00564083456993103,-0.07806110382080078,-0.039682336151599884,-0.026934146881103516,0.013313711620867252,0.00146891747135669,-0.002897098194807768,-0.05405999720096588,-0.07648914307355881,0.006278244312852621,0.0250938069075346,0.04159935936331749,-0.014463924802839756,-0.008832674473524094,-0.019821997731924057,0.0072655100375413895,2.960899146273732E-4,0.007687254808843136,0.07154323160648346,-0.008708068169653416,0.001612694002687931,0.015393679961562157,0.034506380558013916,-0.01664932817220688,-0.05651378259062767,0.05371493101119995,0.029886359348893166,0.010984530672430992,0.015949616208672523,-0.016754765063524246,0.018067924305796623,-0.0352923609316349,0.002079967875033617,-0.01976448856294155,0.04182939976453781,-8.494799840264022E-4,-0.01960154063999653,-0.05620706081390381,-0.021221423521637917,-0.06399016827344894,0.04474327340722084,0.030518976971507072,0.04355471953749657,-0.05448174104094505,0.02812270075082779,-0.019898679107427597,-0.03366289287805557,0.002059599617496133,-0.018566349521279335,-0.02179653011262417,1.1225057096453384E-4,0.046276889741420746,0.04528003931045532,0.038282912224531174,-0.01926606334745884,-0.07982476055622101,0.008430100046098232,0.06744080036878586,0.03130495548248291,-1.6818864969536662E-4,-0.08848969638347626,-0.015470360405743122,-0.023943593725562096,-0.0286211259663105,0.06655897200107574,-0.03492812439799309,0.05126114562153816,-0.02264001965522766,-0.026224849745631218,0.012594829313457012,-0.00972888246178627,0.01056278683245182,0.0254388712