INSERT INTO `knowledge_doc` VALUES (39, '土壤连作障碍与轮作制度', '种植标准', '同科蔬菜连作 3 年以上会出现土传病害加重、产量品质下降的连作障碍（如番茄青枯病、白菜软腐病）。科学轮作原则：茄科（番茄辣椒）与葫芦科（黄瓜南瓜）或十字花科轮作，忌同科连作；水旱轮作效果最佳；配合增施腐熟有机肥和微生物菌剂改良土壤。', '[-0.010564731433987617,0.02243543416261673,-0.05395419895648956,0.01099355798214674,-0.0534084178507328,7.528832647949457E-4,0.0028872708790004253,0.13324815034866333,-0.03954951837658882,0.0032917323987931013,-0.044364072382450104,0.03372137248516083,-0.014258488081395626,0.03925713524222374,0.0434284508228302,-0.040309712290763855,-0.04385727643966675,-0.02107098512351513,0.023215118795633316,0.001598354079760611,-0.04658617451786995,-0.004887649789452553,-0.04452000930905342,-0.01699713245034218,0.01090584322810173,0.05683903396129608,-0.03972494602203369,-0.012504197657108307,-0.01412204373627901,-0.0034013756085187197,-0.026177922263741493,0.014170774258673191,0.02867291308939457,-0.04947100952267647,-0.042219940572977066,-0.0040860362350940704,0.015184364281594753,-0.06471385061740875,-0.06346635520458221,0.024774489924311638,-0.013361850753426552,0.029744980856776237,0.011422384530305862,-0.029569551348686218,0.02588554099202156,0.0019553035963326693,-0.007231577765196562,-0.03910119831562042,-6.456765695475042E-4,0.028010182082653046,-0.018800152465701103,-0.04323352873325348,0.05095241218805313,-0.0534084178507328,0.08225676417350769,0.018985329195857048,0.06627321988344193,-0.029452599585056305,-0.047365859150886536,0.014385187067091465,-0.016431860625743866,-0.015983540564775467,-0.024267693981528282,-0.0012121663894504309,-0.049977805465459824,0.03619687259197235,0.018878120929002762,-0.03799014911055565,-0.011130002327263355,-0.07161406427621841,-0.041674159467220306,0.05032866448163986,0.05999675765633583,-0.06292057782411575,-0.06837836652994156,-0.012952515855431557,0.02407277189195156,-0.015038173645734787,0.0244236309081316,0.00825978722423315,0.07816341519355774,-0.04950999468564987,0.033428993076086044,0.030076347291469574,-0.0284974854439497,-0.0011122693540528417,