INSERT INTO `knowledge_doc` VALUES (43, '熊蜂授粉与激素坐果', '种植标准', '番茄棚室可用熊蜂授粉替代激素蘸花，果形圆润、汁多籽实、无激素残留顾虑，蜂箱使用期间严禁喷施杀虫剂。激素坐果（对氯苯氧乙酸）是常规手段，但浓度过高会造成果实畸形或空心。消费者可通过种子发育状态判断：有籽饱满多为自然授粉或熊蜂授粉。', '[-0.042497459799051285,0.02109074778854847,-0.06508904695510864,-0.05797980725765228,-0.05695291608572006,-0.05639997497200966,0.017121421173214912,0.11548566073179245,-0.008047265000641346,-0.006995690055191517,-0.019846629351377487,0.038310907781124115,-5.106680910103023E-4,0.01843465492129326,0.043129391968250275,-0.026837382465600967,-0.06576047837734222,-0.02675839141011238,-0.003939704038202763,-0.03491427004337311,-0.08673273772001266,-0.01621301844716072,-0.025573518127202988,0.021130243316292763,0.013882767409086227,0.01774347946047783,-0.0380936823785305,-0.0054504177533090115,-0.0032435909379273653,-0.03404536470770836,0.039278555661439896,0.045933593064546585,-0.014346842654049397,-0.012727515771985054,-0.02235461212694645,-0.014139489270746708,-0.02654116414487362,-0.04281342774629593,-0.061060477048158646,0.012046213261783123,0.006882139947265387,0.008373105898499489,-0.01269789319485426,-0.011285919696092606,-0.026284441351890564,-0.005519535392522812,-0.01324096042662859,-0.032406289130449295,0.007400522008538246,0.016677092760801315,-0.014514699578285217,-0.014119741506874561,-0.04154955968260765,-0.030905447900295258,0.061060477048158646,0.030352506786584854,0.07097391784191132,-0.04538065195083618,0.00989862997084856,-0.03910082206130028,-0.05580753833055496,-0.04395880550146103,-0.041115108877420425,0.004218643065541983,0.0025092163123190403,0.052410900592803955,-0.029207129031419754,3.87552339816466E-4,-0.06260081380605698,-0.08333609998226166,0.013803775422275066,0.03623737767338753,0.05695291608572006,-0.005657770670950413,-0.04905375838279724,-0.028634442016482353,0.031892843544483185,-0.0346575491130352,0.03759998455643654,0.050910063087940216,0.07373861968517303,-0.04723695293068886,-0.026264693588018417,0.009982558898627758,-0.012984237633645535,-0.04455124214291