INSERT INTO `knowledge_doc` VALUES (49, '土豆储存与发芽防控', '储存保鲜', '土豆适宜储存温度 4-10 度、避光、干燥、通风，见光会产生叶绿素与龙葵碱（发芽变绿部分含量高，有毒性）。苹果释放的乙烯可抑制土豆发芽，可同箱放几个苹果。已发芽变绿的土豆龙葵碱含量超标的应整颗丢弃，削芽不足以去除毒素。', '[0.03210332989692688,0.014096963219344616,-0.054038356989622116,0.021588381379842758,-0.05473165214061737,-0.07348908483982086,-0.03472243621945381,0.12040192633867264,-0.0062588974833488464,-0.03304697945713997,-0.0032811067067086697,0.05600268766283989,-0.005888178013265133,0.009393161162734032,0.06432221084833145,-0.048453494906425476,-0.03818890452384949,0.004393264651298523,-0.025478526949882507,-0.03974881395697594,-0.0048410166054964066,0.008618020452558994,-0.04417818784713745,0.02497781626880169,0.036243829876184464,0.0263836607336998,-0.017245670780539513,-0.03739931806921959,0.011747469194233418,0.009210208430886269,0.02805911935865879,0.009956461377441883,-0.03489575907588005,-0.012999248690903187,-0.0108423363417387,0.020221052691340446,0.022050578147172928,-0.04090430215001106,-0.048453494906425476,-0.011198611930012703,0.008218414150178432,-0.007125514093786478,-7.263931911438704E-4,-0.0015238007763400674,0.021588381379842758,-0.0480683334171772,-0.010909739881753922,-0.0022724613081663847,-0.01928703300654888,-0.01366365421563387,0.007332539185881615,-0.054539069533348083,0.009494266472756863,-0.057004112750291824,0.049878597259521484,0.028425022959709167,0.0868157222867012,-0.03857406601309776,0.002386806532740593,-0.026884371414780617,-0.0028694637585431337,-0.07052332907915115,0.0018307275604456663,-0.015753163024783134,-0.03826593607664108,0.07202546298503876,0.06886713206768036,0.003671084064990282,-0.03370175510644913,-0.029734577983617783,-0.010601609013974667,0.042560502886772156,-0.04452483355998993,-0.027866536751389503,-0.04421670362353325,-0.0379578061401844,-0.0013456629822030663,0.016571635380387306,0.024708202108740807,0.028752412647008896,0.09752324968576431,-0.027693213894963264,0.0026961404364556074,-0.00829063169658184,0.05704262852668762,0.00821359921246767,0