INSERT INTO `knowledge_doc` VALUES (50, '洋葱大蒜生姜储存', '储存保鲜', '洋葱大蒜耐储：干燥通风常温（15-25 度）可存 1-3 个月，忌潮湿（发芽发霉）。生姜适宜 12-15 度避光，冷藏易受冻，可用保鲜膜包好放阴凉处或埋入沙中。三者均不建议冷藏，家庭常温阴凉处存放即可，出芽的蒜和姜仍可食用。', '[-0.04887964576482773,0.03110179863870144,-0.06035409867763519,0.002377928700298071,-0.01735321804881096,-0.046728186309337616,-0.02693098783493042,0.07843390852212906,-0.017598560079932213,-0.029893962666392326,0.03338536620140076,0.061297718435525894,-0.00821895245462656,0.05529627948999405,0.04129292070865631,0.00362822855822742,-0.030195921659469604,-0.008091563358902931,-0.018834706395864487,-0.0348951630294323,6.115853320807219E-4,0.035404715687036514,-0.02162782847881317,0.028195440769195557,0.05567372962832451,0.02030675671994686,-0.04895513877272606,-0.01186133548617363,0.045142900198698044,-0.007449899800121784,-0.04321791231632233,-0.023382965475320816,0.011795281432569027,-0.011436705477535725,0.06114673987030983,0.04680367931723595,-0.0334797278046608,-0.0523521788418293,-0.03506501391530037,0.005949540063738823,0.0218165535479784,-0.02313762530684471,0.015248940326273441,-0.03400815650820732,-0.0308942012488842,-0.02370379865169525,-0.02598736435174942,-0.007143222726881504,0.004333586432039738,0.01077616959810257,0.025591043755412102,-0.03332874923944473,0.009841983206570148,-0.025572171434760094,0.07798096537590027,0.07016777247190475,0.0608447827398777,-0.008473730646073818,0.007006397470831871,-0.003835825715214014,0.051370810717344284,-0.028554018586874008,0.00449164304882288,0.0017810874851420522,-0.02353394590318203,0.038613032549619675,0.013059736229479313,0.006742183119058609,-0.05416393280029297,-0.010087325237691402,0.033498600125312805,0.036348339170217514,-0.045029666274785995,-0.017655177041888237,-0.04299144446849823,-0.04744534194469452,-0.009983526542782784,0.015739623457193375,0.03855641558766365,0.022137384861707687,0.08741719275712967,-0.028101079165935516,0.08220839500427246,-0.03544246405363083,0.044576726853847504,-0.004107117187231779,-0.01079504191875457