INSERT INTO `knowledge_doc` VALUES (52, '大白菜与菠菜储存差异', '储存保鲜', '大白菜耐储，0-5 度可存 2-4 周，外层叶有保护作用，吃时再剥；菠菜生菜等柔嫩叶菜呼吸强，0-4 度仅存 3-5 天，需厨房纸包裹吸潮再装袋。白菜帮有黑斑（储存中生理性病变）面积大时建议弃食，小黑点不影响安全但口感差。', '[0.0032610450871288776,-0.007846517488360405,-0.06399175524711609,0.02568817511200905,-0.02666005678474903,-0.050118617713451385,-0.011119472794234753,0.11334811896085739,-0.013682574033737183,0.003928022924810648,0.012034185230731964,0.07271964102983475,-0.017684441059827805,0.04996616765856743,0.0422673374414444,0.017465291544795036,-0.04950881004333496,-0.0247353482991457,-0.02239139750599861,0.005897989496588707,-0.01778925210237503,0.0036493216175585985,-0.03462567552924156,-0.012710691429674625,0.029347024857997894,-0.03536888211965561,-0.051147669553756714,-0.02542138285934925,0.06406798213720322,0.025154592469334602,0.008289581164717674,-0.01767491176724434,0.01810368336737156,-0.025364214554429054,0.02275347150862217,-0.02315365895628929,-0.022715359926223755,-0.06406798213720322,-0.04066659137606621,-0.014378136023879051,0.012300976552069187,-0.01900886744260788,0.00990938488394022,0.006107611116021872,-0.020885935053229332,-0.03525454178452492,-0.018513398244976997,-0.011881733313202858,-0.02911834605038166,0.0072938790544867516,0.030471358448266983,-0.030471358448266983,0.0527484193444252,-0.05793178826570511,0.0378652848303318,0.04516392573714256,0.08430599421262741,-0.02342044934630394,-0.011081360280513763,0.01346342358738184,0.0021736330818384886,-0.02002839185297489,0.004921343643218279,-0.05583557114005089,-0.03918018192052841,0.0436394065618515,0.015016529709100723,-0.005183370318263769,-0.03708396852016449,-0.023496676236391068,-0.02645043469965458,0.0199140515178442,0.03538793697953224,-0.029175516217947006,-0.010442967526614666,-0.044897135347127914,-0.004887994844466448,4.9539481551619247E-5,0.048784662038087845,0.04165752977132797,0.09032785147428513,-0.02627892605960369,0.06029479578137398,-0.027765333652496338,0.012472485192120075,0.012281919829547405,1.482090301578