INSERT INTO `knowledge_doc` VALUES (53, '苹果储存与乙烯释放', '储存保鲜', '苹果是乙烯释放大户，4 度冷藏可存 1-2 个月，常温可存 2 周。切记与叶菜、黄瓜、胡萝卜隔离存放，乙烯会导致叶菜黄化、黄瓜发苦、萝卜发苦。家庭可把需后熟的水果（猕猴桃、芒果、香蕉）与苹果同袋催熟。', '[-0.002319356659427285,0.019388778135180473,-0.030078193172812462,0.016166793182492256,-0.05640372261404991,-0.05113482475280762,-0.0482160821557045,0.10340682417154312,-0.02888416312634945,-0.03496803343296051,0.04488037899136543,0.06538737565279007,-0.007457951549440622,0.003195926547050476,0.06447763741016388,0.014081977307796478,-0.027557462453842163,0.009950253181159496,-0.058109477162361145,-0.026211809366941452,0.009722818620502949,-0.008595123887062073,-0.036522168666124344,0.006841983646154404,0.005818529054522514,0.009661221876740456,-0.08324097841978073,-0.015276007354259491,0.047457970678806305,-0.033243320882320404,0.020108988508582115,-0.006211800966411829,-0.020184800028800964,-0.02012794092297554,0.026192856952548027,0.03271264210343361,-0.016034122556447983,-0.061824239790439606,-0.05651743710041046,-0.0084624532610178,-0.03417201340198517,-0.016507944092154503,0.008320307359099388,0.01156124658882618,0.009087897837162018,-0.033053793013095856,-0.033091697841882706,-0.020734433084726334,-0.00990287121385336,-0.023710031062364578,0.04889838770031929,-0.005955937318503857,0.02388060837984085,-0.015816165134310722,0.05113482475280762,0.03724237531423569,0.05105901509523392,-0.025700083002448082,-0.044577132910490036,0.003248046850785613,0.005842220038175583,-0.021246159449219704,0.004970388486981392,-0.020298516377806664,-0.02829662524163723,0.03606729954481125,0.0214356891810894,-0.004515519831329584,-0.07179344445466995,-0.01589197665452957,-0.029547514393925667,0.06334047019481659,-0.04707891121506691,-0.042568132281303406,-0.03030562773346901,-0.03927033394575119,0.02909264527261257,0.013039570301771164,0.023217257112264633,0.013541820459067822,0.11007823050022125,-0.03282636031508446,0.019123438745737076,-0.02727317065000534,0.04290928319096565,-6.657193298451602E-4,-0.028865210711956