INSERT INTO `knowledge_doc` VALUES (55, '柑橘类水果储存', '储存保鲜', '柑橘橙柚适宜 5-10 度储存，湿度 85-90%，可存 2-4 周；过冷（低于 3 度）会发生冷害（果皮凹陷、异味）。表皮机械伤和霉斑果要及时挑出，霉菌会扩散传染整箱。柚子类厚皮果常温阴凉存放即可，越放越甜（淀粉糖化）。', '[-0.02256697230041027,-0.0017351994756609201,-0.04577174782752991,0.026243720203638077,-0.02579350583255291,-0.0730472058057785,-0.04329557344317436,0.07376004755496979,-0.06261724978685379,-0.02645006775856018,0.058452773839235306,0.041419681161642075,-0.06051625311374664,0.041532233357429504,0.06468073278665543,0.026656415313482285,-0.016770469024777412,0.001997824292629957,-0.07548587024211884,-0.024724246934056282,0.015110304579138756,-0.027781950309872627,-0.057102132588624954,0.02241690084338188,-0.012455918826162815,0.010195469483733177,-0.08081340044736862,-0.007573910988867283,0.055413831025362015,-0.04220755398273468,0.0017715449212118983,0.021272607147693634,0.017867865040898323,-0.04487131908535957,-0.008694755844771862,0.02667517401278019,-0.008366474881768227,-0.03682374581694603,-0.0480603352189064,0.0051493216305971146,-0.0033343967515975237,0.006851693149656057,0.012409021146595478,0.03164628520607948,1.3226499140728265E-4,-0.013290690258145332,0.012024463154375553,-0.004234824795275927,-0.007334735244512558,0.018402494490146637,0.013497037813067436,-0.007006454281508923,0.0395813062787056,-0.04963608458638191,0.03678622841835022,0.015579277649521828,0.07323479652404785,-0.058377739042043686,-0.03779920935630798,0.008000676520168781,0.012090119533240795,-0.0234486423432827,-0.029995502904057503,-0.014416225254535675,-0.03564193472266197,0.03483530133962631,0.009548286907374859,-0.041419681161642075,-0.047797709703445435,-0.03950627148151398,0.0032171537168323994,0.020053278654813766,-0.044796284288167953,-0.03260299190878868,-0.04059428721666336,-0.04224507138133049,-0.018927743658423424,0.017380133271217346,0.001673060585744679,0.024424105882644653,0.06486832350492477,-0.004171513486653566,0.04340812563896179,-0.012174534611403942,0.05139942094683647,0.02498687244951725,0.0242