INSERT INTO `knowledge_doc` VALUES (57, '乙烯催熟与保鲜原理', '储存保鲜', '乙烯是果蔬自身释放的催熟激素：猕猴桃、香蕉、芒果、番茄采后持续释放乙烯后熟；乙烯敏感型果蔬（叶菜、黄瓜、胡萝卜）受乙烯影响加速衰老变黄。储存原则：呼吸高峰型水果（苹果香蕉）与呼吸非高峰型蔬菜分区存放，冷库可用乙烯脱除机或高锰酸钾载体吸附。', '[-0.009811542928218842,0.010425354354083538,0.0022356908302754164,-0.01736614666879177,-0.08362947404384613,-0.06009688228368759,-0.020642956718802452,0.14482177793979645,-0.037338633090257645,-0.018716532737016678,0.005004925653338432,0.03567662090063095,-0.05224009230732918,0.0044949897564947605,0.060890112072229385,0.01534529123455286,-0.02345704846084118,0.0018969139782711864,-0.03875512257218361,-0.034770067781209946,-0.05103135481476784,0.0039543635211884975,-0.05696171894669533,0.0028919971082359552,0.024722443893551826,0.03059614822268486,-0.03257923200726509,-0.026667755097150803,0.007852067239582539,-0.024344714358448982,0.0017269353847950697,0.03380685672163963,-0.04351452365517616,-0.003555385861545801,0.0019760013092309237,0.01251231413334608,-0.0031162744853645563,-0.07297748327255249,-0.06493182480335236,0.011851286515593529,0.004579978995025158,-0.05439315363764763,0.04952043294906616,-0.01864098757505417,0.012993919663131237,-0.04634749889373779,-0.022134991362690926,-0.04668745771050453,-0.023343728855252266,-0.02672441489994526,-0.029935121536254883,0.0030265634413808584,0.02139841765165329,-0.030237305909395218,0.08015435934066772,0.04321233928203583,0.00794177781790495,-0.055488571524620056,-0.05696171894669533,-0.0033854071516543627,0.022531608119606972,-0.006657495629042387,-0.004476103466004133,-0.0034703966230154037,-0.022720472887158394,0.049898162484169006,0.010614220052957535,-0.003935476765036583,-0.049029383808374405,-0.02449580654501915,0.007899283431470394,0.07293970882892609,-0.014788138680160046,-0.04185251146554947,-0.011114711873233318,-0.024099189788103104,0.03307028114795685,-0.006175889167934656,0.052655596286058426,0.027876490727066994,0.06780257821083069,-0.03815075382590294,-0.011095825582742691,0.0032130677718669176,0.05065362527966499,0.0073