INSERT INTO `knowledge_doc` VALUES (58, '果蔬冻害识别与预防', '储存保鲜', '热带亚热带果蔬（香蕉、芒果、番茄、黄瓜、青椒）在 0-4 度普通冷藏易发生冷害：表皮水渍状凹陷、褐变、不能正常后熟变味。香蕉适宜 12-14 度，芒果 10-13 度。冰箱冷藏不是万能，热带水果常温存放更快更安全，已发生冷害的尽快食用。', '[-0.012182925827801228,-0.026028016582131386,-0.05383153259754181,0.00118169654160738,-0.041894152760505676,-0.04015643149614334,0.00431360537186265,0.0882459357380867,-0.061311278492212296,-0.0306745283305645,0.009859669953584671,0.008391108363866806,-0.038173165172338486,0.01375065091997385,0.07902846485376358,0.011937377974390984,-0.028332384303212166,0.019020473584532738,-0.009618844836950302,-0.024384738877415657,3.2375651062466204E-4,-0.016036130487918854,-0.07555302232503891,-0.01552614662796259,0.035226598381996155,0.025631364434957504,-0.05436040088534355,-0.013533435761928558,0.07710186392068863,0.014515625312924385,0.07234202325344086,-0.005534259136766195,0.01954934559762478,-0.027161313220858574,0.025234710425138474,0.06161349266767502,-0.013202891685068607,-0.07963288575410843,-0.06724219024181366,-0.020248210057616234,0.0036430724430829287,0.02276034839451313,0.040458645671606064,-0.0066817207261919975,0.010520759038627148,-0.011266845278441906,0.00359349069185555,-0.02942790277302265,-0.024120302870869637,-0.011861825361847878,0.05609812214970589,-0.028105726465582848,0.006672276649624109,-0.039325349032878876,0.015422261320054531,0.0191715806722641,0.07094429433345795,-0.08257945626974106,-0.047371748834848404,0.007748906966298819,-0.029749004170298576,-0.00791890174150467,-0.011455727741122246,-0.020531535148620605,-0.025876911357045174,0.020134881138801575,0.04642733559012413,-0.06172682344913483,-0.07147315889596939,-0.026500223204493523,-0.0017270949902012944,0.04899613559246063,0.01826494373381138,-0.011559613049030304,-0.02661355398595333,-0.01712220534682274,-0.018538823351264,0.023194778710603714,0.0409497395157814,-0.013693985529243946,0.06822438538074493,-0.031108958646655083,-0.008971922099590302,-0.038022059947252274,0.04178082197904587,0.013826203532516956