INSERT INTO `knowledge_doc` VALUES (60, '家庭冰箱分区存放原则', '储存保鲜', '冰箱科学分区：冷藏室上层（温度稳定）放剩菜熟食；中层放乳制品豆制品；下层（最冷）放需即食的生鲜肉类；果蔬抽屉高湿度区放蔬菜水果。生熟分离、包装密封防串味与交叉污染。冰箱不是保险箱，冷藏仅延缓变质，2-3 天内食用完最佳。', '[-0.015645582228899002,0.005530824884772301,-0.06029035896062851,0.050695180892944336,-0.012596101500093937,-0.010401252657175064,0.01931661181151867,0.0585034042596817,-0.03762320429086685,-0.008026736788451672,0.024570653215050697,0.08010227233171463,-0.021462902426719666,0.05617259070277214,0.07948072254657745,0.0029547910671681166,-8.540244307368994E-4,8.540244307368994E-4,-0.0380699448287487,-0.042343102395534515,-0.0024910562206059694,-0.01443161629140377,-0.04789820685982704,0.029795559123158455,0.047975897789001465,0.005006392020732164,-0.05729915201663971,0.027115123346447945,0.04207117483019829,-0.005890158470720053,0.018889296799898148,-0.030902694910764694,-0.008915359154343605,-0.008560881949961185,0.02466776967048645,0.0018258034251630306,-0.024959120899438858,-0.0599018931388855,-0.059008412063121796,-0.021055009216070175,-0.0060892486944794655,0.020239224657416344,0.004901990760117769,-0.024065643548965454,0.013450732454657555,-0.006618537474423647,-0.0220261812210083,-0.0386720709502697,-0.019569117575883865,-0.03680742159485817,0.0697690024971962,-0.014528733678162098,0.044207751750946045,-0.028183413669466972,-0.002775124041363597,0.07932533323764801,0.05648336559534073,-0.08344310522079468,-0.037448395043611526,-0.008687133900821209,0.008570593781769276,-0.002404864877462387,-0.027930907905101776,0.002857673680409789,0.029698440805077553,-0.001819733646698296,0.03674915060400963,-0.02352178655564785,-0.08204461634159088,-0.021909641101956367,-0.03517585247755051,0.01899612508714199,-0.002869813470169902,-0.035875096917152405,-0.030514225363731384,0.009784558787941933,0.014412193559110165,-0.03366082161664963,0.0317961722612381,0.05112249776721001,0.07011862099170685,-0.04284811019897461,0.05718261003494263,-0.04284811019897461,0.05648336559534073,0.011702623218297958,-0.01