INSERT INTO `knowledge_doc` VALUES (61, '果蔬失水萎蔫与保湿', '储存保鲜', '果蔬采后失水是品质下降主因：失水超 5% 外观明显萎蔫。保湿要点：叶菜用带孔保鲜袋（防缺氧）、根茎类带泥或用微湿沙埋、瓜果类可涂果蜡保鲜。冷库湿度一般维持 85-95%。家庭蔬菜蔫了可泡清水 30 分钟部分恢复脆度，但营养已流失。', '[-0.035384733229875565,0.042684514075517654,-0.03469317406415939,-0.043529752641916275,-0.03455870598554611,-0.07019317150115967,0.01337012741714716,0.10188958793878555,-0.06792639195919037,-0.015367962419986725,-0.011852541007101536,0.014657193794846535,-0.045412328094244,0.06569804251194,0.08898050338029861,0.03845832496881485,-0.027393393218517303,-0.009753854013979435,-0.003947645425796509,-0.010094830766320229,-0.0023159999400377274,0.02115015871822834,-0.013725511729717255,-0.017279352992773056,0.02614474669098854,0.05002271756529808,-0.07345885783433914,-0.008029760792851448,0.02070832997560501,0.004776074551045895,0.05305789038538933,0.013149213045835495,-0.0010055209277197719,-0.0019726220052689314,-0.07368937879800797,0.017010413110256195,0.027220504358410835,-0.10288850963115692,-0.03968776389956474,0.045220229774713516,0.007222942542284727,0.03605708107352257,4.13839406974148E-5,-0.014561144635081291,0.02814258076250553,-0.010680734179913998,0.008826973848044872,-0.034654755145311356,0.008476391434669495,0.002538115018978715,-0.01336052268743515,-0.03482764586806297,0.06350810825824738,-0.014849293977022171,0.06946319341659546,0.008140217512845993,0.0408787801861763,-0.03177326172590256,0.0022367588244378567,-0.008577244356274605,-0.021630406379699707,0.005263527389615774,-0.013629461638629436,-0.027047613635659218,-0.011564391665160656,0.10304218530654907,0.018633654341101646,-0.010527054779231548,-0.06731167435646057,-0.04940799996256828,-0.0011045723222196102,0.08421643823385239,-0.010959277860820293,-0.02731655351817608,-0.011823725886642933,-0.024089280515909195,0.014465094543993473,0.039649344980716705,0.007635956164449453,0.029218338429927826,0.07783873379230499,0.011410712264478207,0.014541934244334698,-0.01888338476419449,-0.023359302431344986,0.003714724676683545,0.0