INSERT INTO `knowledge_doc` VALUES (62, '气调冷藏（CA）保鲜技术', '储存保鲜', '气调冷藏通过降低氧气（2-5%）提高二氧化碳（3-5%）浓度，抑制果蔬呼吸作用，比普通冷藏延长保鲜期 0.5-1 倍。苹果梨大蒜等耐低氧品种效果好，消费者日常可用保鲜盒或保鲜膜营造简易小气调环境。溯源流通记录中标注气调库储存可提升产品档次与可信度。', '[-0.04787071794271469,-4.899445339106023E-4,-0.054671816527843475,-0.008313498459756374,-0.03451275825500488,-0.0805610865354538,0.02414202317595482,0.13962920010089874,-0.04456410929560661,0.023183856159448624,-0.010455280542373657,-0.0033277478069067,-0.010868607088923454,0.06038323789834976,0.07334665954113007,-0.013104327954351902,-0.037800583988428116,0.01420340035110712,-0.014588545076549053,-0.019144529476761818,-0.01472005806863308,0.011319508776068687,-0.04140779748558998,0.03368610516190529,0.05106460675597191,0.020440872758626938,-0.06988974660634995,-0.03708665445446968,0.053807590156793594,-0.003224416170269251,0.056888751685619354,0.06117231771349907,-0.03130008652806282,-0.053995467722415924,0.014560364186763763,0.00480257160961628,-0.008365163579583168,-0.10438372194766998,-0.07710417360067368,-0.008764400146901608,0.0055752103216946125,-0.0018940215231850743,0.028932852670550346,-0.013160690665245056,-0.0039759185165166855,-0.02692258358001709,0.007129881531000137,-0.019576644524931908,-0.011047089472413063,-0.024066872894763947,0.07578904181718826,-0.0505385547876358,0.0021300404332578182,-0.024592924863100052,0.00809744093567133,0.00803638156503439,0.014447638764977455,-0.07447391003370285,-0.04392533004283905,0.014118855819106102,-0.009168332442641258,-0.026490468531847,-0.03524547442793846,-0.009882260113954544,0.012503125704824924,0.030717670917510986,0.01638275757431984,-0.004757951013743877,-0.03873996064066887,-0.04430108144879341,-0.02438626065850258,0.09213422238826752,4.0833602542988956E-4,-0.039529040455818176,-0.03584667667746544,-0.029966168105602264,0.025645028799772263,0.00617641257122159,0.036447878926992416,2.276524610351771E-4,0.06260017305612564,-0.0032502489630132914,0.06440377980470657,0.0013609243324026465,0.018937867134809494,0.00516658