INSERT INTO `knowledge_doc` VALUES (70, '检测报告有效期与批次对应', '检测知识', '检测报告只对来样批次负责，不存在一年有效的通用检测报告。同一地块不同批次用药不同，需分别检测；同一批次分次采收的，抽检覆盖即可。消费者扫码时应核对：报告上的样品编号、采收日期与溯源批次信息是否对应，张冠李戴的报告无意义。', '[-0.06814166158437729,0.018894173204898834,-0.05955688655376434,-0.047024644911289215,-0.03932134062051773,-0.07523176819086075,-0.02636752650141716,0.07473354041576385,-0.041160937398672104,-0.002259971108287573,-0.02690407633781433,0.07557669281959534,0.029280219227075577,0.048136066645383835,-0.02491118013858795,-0.0014838919742032886,0.009734522551298141,-0.06902313232421875,-0.06568887084722519,-0.03589126467704773,-0.00501097971573472,0.0024252471048384905,0.008488964289426804,0.019852295517921448,0.03146473690867424,0.018290555104613304,-0.0653439462184906,0.005825384054332972,0.05403809994459152,0.016834208741784096,-0.014879640191793442,-0.02979760430753231,0.029931742697954178,0.007435029372572899,-0.024662069976329803,-0.01647012308239937,0.012963395565748215,-0.038880605250597,-0.033515118062496185,0.01030939631164074,0.018568411469459534,-0.010826782323420048,-0.015655718743801117,-0.05618429556488991,-0.005834965035319328,-0.07159090042114258,0.05629926919937134,-0.06549724191427231,0.004287597257643938,-0.008134459145367146,0.0016036572633311152,0.037730857729911804,0.0717058777809143,-0.09680867940187454,0.033745069056749344,0.05120205879211426,0.008541660383343697,-0.03125395253300667,0.005197813734412193,-0.06017008423805237,0.02903110720217228,0.0038756048306822777,0.00742065766826272,-0.018137255683541298,-7.617072551511228E-4,0.011008826084434986,0.01633598655462265,-0.010520183481276035,-0.014362254180014133,-0.03211626037955284,-0.010826782323420048,0.027517274022102356,-0.020446330308914185,-0.0023090748582035303,-0.04782946780323982,-0.04246398061513901,0.011142962612211704,-0.024872856214642525,0.0014120327541604638,-0.01063515804708004,0.06396424770355225,-0.005849336739629507,0.022707499563694,0.021442778408527374,-0.013691568747162819,-0.01782107539474964,-0.019