INSERT INTO `knowledge_doc` VALUES (73, '微生物污染与大肠杆菌指标', '检测知识', '即食蔬菜的微生物指标比农残更直接关系急性食源性疾病：大肠菌群、沙门氏菌、李斯特菌是重点检测项。污染途径主要是未腐熟粪肥、污染灌溉水、采收人员手部卫生。生食沙拉菜风险高于熟食蔬菜，免疫力低下人群建议熟制后食用。', '[-0.04008155316114426,-0.026982493698596954,-0.06710326671600342,-5.98392216488719E-4,-0.04314061626791954,-0.0010589059675112367,-0.010549841448664665,0.09294841438531876,-0.04674873873591423,0.0046572256833314896,-0.010035095736384392,0.05361201986670494,-0.002725702477619052,0.0034953702706843615,0.02664913423359394,-0.02906108647584915,-0.04129733517765999,-0.03786569461226463,-0.019727027043700218,-0.02351163513958454,-0.0465918630361557,0.05031764507293701,-0.04784686490893364,-0.010755740106105804,0.07208404690027237,0.02702171355485916,-0.030708273872733116,-0.01670718379318714,-1.0187680891249329E-4,-0.00401992117986083,0.005372967571020126,-0.09514466673135757,0.015942418947815895,0.008074158802628517,-0.029668977484107018,0.0010104953544214368,-0.03025725856423378,-0.04992545768618584,-0.050905924290418625,0.053415924310684204,-0.011393044143915176,-0.001137956278398633,-0.02627655677497387,-0.017393512651324272,0.009162478148937225,-0.04788608476519585,0.01324613019824028,-0.061220455914735794,-0.051219675689935684,-0.014971754513680935,0.001368979224935174,0.007476072758436203,0.06796608120203018,-0.0931837260723114,0.048239052295684814,0.009770369157195091,0.07149576395750046,0.01274609100073576,-0.0025222552940249443,0.01094202883541584,-0.010716521181166172,-0.013922653160989285,0.024158744141459465,-0.030237648636102676,0.012402926571667194,0.026982493698596954,0.020197652280330658,-0.01460898108780384,-0.02764921262860298,-0.0022636568173766136,-0.047611553221940994,-0.005152361933141947,7.678294205106795E-4,-0.022217417135834694,-0.02815905585885048,-0.04953327029943466,0.023590072989463806,-0.028100227937102318,0.018609292805194855,0.004877830855548382,0.0691034197807312,-0.00409590732306242,0.013334372080862522,-0.008652634918689728,0.04772920906543732,0.012069568037986755,0.