INSERT INTO `knowledge_doc` VALUES (75, '先进先出（FIFO）库存管理', '流通标准', '生鲜库存执行先进先出原则：按批次入库时间先后出库，早入库先销售，避免压库变质。库位管理按批次分区、标识卡注明入库日期与保质期。每日盘点临期品（剩余货架期低于三分之一）优先促销处理。溯源系统中的出入库记录可自动校验 FIFO 执行情况。', '[-0.046027377247810364,-0.034761663526296616,-0.043403852730989456,0.04108898341655731,-0.04259364679455757,-0.03063347563147545,0.01961854100227356,0.10972493886947632,-0.024942748248577118,0.08765649050474167,-0.02563720941543579,-0.01215307880192995,-0.03487740829586983,0.06635966897010803,0.06998630613088608,0.02476913295686245,0.012644989416003227,-0.00818886049091816,-0.04791785404086113,-0.018316425383090973,-0.032311756163835526,0.01344554964452982,0.020467327907681465,0.03723086044192314,0.03809893876314163,0.005251866299659014,-0.021335406228899956,-0.011545425280928612,0.038581203669309616,0.008806159719824791,0.05343496799468994,0.03161729499697685,-0.033392030745744705,-0.023920346051454544,-0.007769289892166853,-0.0016071482095867395,0.049306776374578476,-0.030266953632235527,-0.08179215341806412,0.013426259160041809,-0.06354324519634247,0.026273800060153008,0.014467950910329819,-0.021431857720017433,0.03159800544381142,-0.04193776845932007,-0.028453636914491653,-0.04695332422852516,-0.0425550676882267,-0.02797137200832367,-0.03549470752477646,0.007817516103386879,0.027817048132419586,-0.03779028728604317,0.049268197268247604,0.09421529620885849,-0.00741723645478487,-0.07835842669010162,0.020544491708278656,-0.016387365758419037,-0.00115080492105335,0.003154013305902481,-0.014400433748960495,0.015056314878165722,0.012143434025347233,0.018721528351306915,0.03923708200454712,-0.02091101184487343,-0.026852518320083618,-0.013821716420352459,-0.02156689204275608,0.048303667455911636,-0.008661480620503426,-0.026582449674606323,-0.037635963410139084,0.0023896233178675175,0.06902177631855011,-0.04633602499961853,0.043828245252370834,-0.012963284738361835,0.04718481004238129,-0.023032978177070618,0.022627875208854675,0.0011652729008346796,0.06269445270299911,0.0492296144366264