INSERT INTO `knowledge_doc` VALUES (85, '如何挑选叶菜类', '消费科普', '叶菜挑选看三点：叶片挺括有光泽不塌蔫、叶柄断面湿润不发黑、无黄叶虫眼水渍斑。散装叶菜比包装净菜更新鲜（可看到完整状态），但注意喷水增重的（盆底积水多的摊位）。早市叶菜多为当日晨采，比下午摊更新鲜。扫码溯源可查到具体采收日期。', '[-0.04933897778391838,0.031940896064043045,-0.06559494882822037,0.012934349477291107,-0.025145364925265312,-0.02577352337539196,-0.014657026156783104,0.1187790185213089,-0.044085290282964706,0.04298125207424164,-0.010450269095599651,0.017169659957289696,-7.0132443215698E-4,0.06121687963604927,0.054592665284872055,0.02375580370426178,-0.08177478611469269,-0.01795961521565914,0.036433178931474686,-0.021128959953784943,-0.05227038264274597,0.0403544083237648,-0.03649028390645981,0.022804047912359238,0.00875614583492279,-0.002202122937887907,-0.040697041898965836,-0.035728879272937775,0.008370684459805489,0.030970105901360512,-0.0015489811776205897,-0.022099750116467476,0.04366651549935341,-0.016436807811260223,-0.07438916712999344,-0.012839173898100853,0.015389877371490002,-0.07366583496332169,-0.027524752542376518,0.04465634375810623,0.012496542185544968,-0.02512633055448532,0.008718075230717659,-0.011944524943828583,0.0028219535015523434,-0.05295564606785774,-0.04385686665773392,-0.03668063506484032,0.01677943952381611,0.011801761575043201,-0.001289627980440855,-0.016179833561182022,0.03470098599791527,-0.04812072962522507,0.03277844190597534,0.009926804341375828,0.0938049703836441,-0.04412335902452469,0.030170632526278496,0.02826712280511856,-0.004275759216398001,0.03405379131436348,0.007299960590898991,-0.012915314175188541,-0.028552647680044174,0.03277844190597534,0.014466674998402596,0.011468647047877312,-0.04054475948214531,-0.025735454633831978,-0.022518521174788475,0.005943709518760443,0.007771078962832689,-0.029523437842726707,-0.01994878426194191,-0.043400026857852936,0.0228801891207695,-0.010374128818511963,0.03780370578169823,0.043590378016233444,0.05687687546014786,-0.0287049300968647,0.009484237991273403,-0.013039043173193932,0.02080536261200905,0.023375101387500763,0.0025364269968