INSERT INTO `knowledge_doc` VALUES (87, '有机菜与普通菜营养价值', '消费科普', '研究综述表明有机与常规种植蔬菜的宏量营养差异不大，有机菜的部分抗氧化物（多酚类）略高、农残检出率更低，但价格高 2-5 倍。性价比建议：常规菜按清洗规范处理已足够安全；预算有限时优先为儿童常吃的品类（菠菜草莓）选择有机或绿色认证产品。', '[-0.05318840220570564,-0.011422364041209221,-0.03573595732450485,0.029280679300427437,-0.036663662642240524,-0.04263576120138168,0.03422844037413597,0.07827508449554443,-0.013770616613328457,0.012871903367340565,-0.0013106245314702392,0.013094165362417698,-0.016109205782413483,-0.005865799728780985,0.04232652857899666,0.023753106594085693,-0.07541466504335403,0.013857589103281498,-0.03152263164520264,0.014108842238783836,-0.06953919678926468,-0.0014894009800627828,-0.0068224952556192875,-0.010011480189859867,0.0287201926112175,0.007242861203849316,-0.06269737333059311,-0.0377846397459507,0.007653563749045134,0.009499309584498405,-8.017760410439223E-5,-0.022322895005345345,0.053497638553380966,-0.02431359514594078,-0.05021201819181442,-0.05357494577765465,-0.007146225310862064,-0.05631940811872482,-0.05442534387111664,-3.108580858679488E-5,0.03102012723684311,-0.024603502824902534,-0.003522378858178854,0.016031896695494652,0.02207164093852043,-0.042017292231321335,0.005136198364198208,-0.01971372589468956,-0.027715178206562996,-0.021027972921729088,0.01816754974424839,-0.04487771540880203,0.09671321511268616,-0.05767231062054634,0.04777679219841957,0.01482394803315401,0.021066628396511078,-0.05434803292155266,0.008542614057660103,0.0279084499925375,-0.023347236216068268,0.0020208985079079866,0.0021960509475320578,-0.01550039928406477,0.02129855379462242,0.021723752841353416,0.0014229636872187257,-0.0023675798438489437,-0.04193998500704765,-0.017964614555239677,-0.024719465523958206,0.003937913104891777,0.01979103311896324,-0.020177576690912247,0.0046119485050439835,-0.04630792886018753,0.02124057337641716,-0.019133910536766052,0.0486658439040184,0.02958991564810276,0.032856207340955734,-0.02945462428033352,0.009296374395489693,0.0022165861446410418,-0.03154195845127106,0.01801293343305