INSERT INTO `knowledge_doc` VALUES (88, '隔夜菜的安全处理', '消费科普', '隔夜菜安全要点：吃不完的菜 2 小时内（夏季 1 小时内）密封冷藏、下次食用彻底加热沸腾 3 分钟以上。亚硝酸盐风险主要在隔夜叶菜，建议叶菜当餐吃完，瓜果肉类冷藏 1-2 天内食用。反复加热的菜营养流失且易滋生细菌，分装小份加热一次吃完为宜。', '[0.010008872486650944,7.828334346413612E-4,-0.025278575718402863,0.017928607761859894,-0.055609069764614105,-0.03414791822433472,0.05420364812016487,0.08622444421052933,-0.10043058544397354,0.0070460946299135685,-0.010208291001617908,0.05792611464858055,-0.022068899124860764,0.030824290588498116,0.06309198588132858,-0.033749084919691086,0.015905940905213356,-0.0356672927737236,0.010958481580018997,-0.041250988841056824,-0.02092937007546425,0.056824568659067154,-0.03878200799226761,-0.013683857396245003,0.0668904185295105,-0.0012487351195886731,-0.05393775925040245,-0.003926631063222885,0.04463159665465355,-0.008812366053462029,0.023531297221779823,-0.06738421320915222,0.0037272130139172077,-0.02835530787706375,-0.011537742801010609,0.014566993340849876,0.009752478450536728,-0.05967339500784874,-0.07038497924804688,0.03236265480518341,0.0033260034397244453,-0.05484938248991966,-0.02079642564058304,-0.020283635705709457,0.013978236354887486,-0.04045331850647926,2.605488116387278E-4,-0.028678175061941147,0.02091037854552269,-0.002257694024592638,0.032723505049943924,-0.008442019112408161,0.028697166591882706,-0.0662446841597557,0.07653844356536865,0.03542039543390274,0.06495321542024612,-0.0036726107355207205,0.010227282531559467,0.03712968900799751,0.0038601583801209927,0.007183787878602743,0.04732848331332207,-0.038933947682380676,-0.01918208971619606,0.02850724570453167,0.05553309991955757,-0.0016665627481415868,-0.03973161801695824,-0.002499844180420041,0.02279060333967209,0.042428504675626755,0.017520274966955185,-0.028849104419350624,-0.048012200742959976,-0.02892507240176201,0.03597116842865944,-0.03479365259408951,0.06142067536711693,0.05606488138437271,0.08189423382282257,-0.015041797421872616,-2.2953817097004503E-4,0.016941014677286148,0.061876486986875534,0.04645484313368797,