INSERT INTO `knowledge_doc` VALUES (92, '果蔬营养烹饪保留技巧', '消费科普', '营养保留原则：先洗后切（切后水洗流失水溶性维生素）、急火快炒缩短加热、现切现炒现吃。番茄红素经加热更易吸收（熟吃好）；青椒西兰花维 C 怕热（快炒或白灼）；胡萝卜素脂溶性（用油炒吸收好）。凉拌菜用焯水 30 秒既去农残又保脆嫩。', '[-0.060178425163030624,0.04913545399904251,-0.016458645462989807,0.027665145695209503,-0.05125170201063156,-0.062179241329431534,0.05429140478372574,0.09557750076055527,-0.040478069335222244,-0.034725721925497055,0.0203159898519516,0.008041745983064175,-0.02962748520076275,0.09234540909528732,0.09373059123754501,0.06333355605602264,-0.05240602046251297,0.011639369651675224,0.018401745706796646,-0.012293482199311256,-0.02339417114853859,0.025760522112250328,-0.031820688396692276,-0.009465404786169529,0.031532108783721924,0.024702396243810654,-0.05421445146203041,-0.03222469985485077,0.0640646293759346,0.012408914044499397,0.01814202591776848,0.018113167956471443,-0.028126873075962067,-0.008527521044015884,-0.02122020535171032,0.014496305026113987,-0.028607837855815887,-0.06902819126844406,-0.05167495086789131,0.013178459368646145,0.00970588717609644,-0.018901951611042023,0.008667001500725746,-0.048866111785173416,1.421103224856779E-4,-0.02689559943974018,0.009802080690860748,-0.035456787794828415,0.024875544011592865,-0.018218979239463806,0.01090830098837614,-0.015515952371060848,0.0327441431581974,-0.07202941924333572,0.05444531515240669,0.02574128285050392,0.04247888922691345,-0.02804991789162159,2.1072308300063014E-4,0.0646417886018753,0.0035880038049072027,-0.0073202974162995815,-0.008561189286410809,-0.03693816438317299,0.012726351618766785,0.044826000928878784,0.038592685014009476,-0.002650120761245489,-0.05252145230770111,-0.037092071026563644,-0.009580835700035095,0.055099427700042725,-0.0029435099568217993,-0.029819872230291367,-0.03495658561587334,-0.026087578386068344,0.03241708502173424,0.010619722306728363,0.04394102469086647,0.0431714802980423,0.03707283362746239,0.009196063503623009,0.03855420649051666,-0.02604909986257553,0.03434094786643982,-0.00867662113159895,-0.00519442