INSERT INTO `knowledge_doc` VALUES (95, '豇豆农残专项治理常识', '法规标准', '豇豆（长豆角）因花期与采收期重叠、采摘频繁，是农残超标重灾区，被农业农村部列为专项治理品种。高风险项目为灭蝇胺、噻虫嗪、克百威。合规做法是登记用药、执行采摘安全间隔期。消费者购买豇豆建议查看检测报告，或焯水 2 分钟后再烹调更安心。', '[-0.04265531152486801,-0.010258622467517853,-0.040342673659324646,-0.025537841022014618,-0.05506844073534012,-0.07198824733495712,0.04384128004312515,0.08965916931629181,-0.032455988228321075,0.037120793014764786,-0.047636374831199646,0.0364685133099556,-0.004388080909848213,0.05649160221219063,0.026961002498865128,-0.08309681713581085,-0.011632367968559265,-0.045224908739328384,0.007397474721074104,-0.057598505169153214,-0.05056176334619522,0.05589861795306206,-0.07372766733169556,0.020151570439338684,-0.0027252554427832365,0.05494984611868858,0.001456516794860363,-0.0013366845669224858,0.013658396899700165,0.004659865517169237,-0.024826260283589363,-0.011701549403369427,-0.009319731034338474,-0.026763342320919037,1.0145584383280948E-4,0.013401436619460583,-0.007921276614069939,-0.019479522481560707,-0.05601721629500389,0.013648513704538345,-0.005104603245854378,0.04067869856953621,-0.007249228656291962,-0.006078085396438837,0.023185672238469124,-0.04150887578725815,0.014636820182204247,-0.04534350335597992,0.034116342663764954,-0.002016145270317793,0.010169674642384052,-0.03757541626691818,0.035065118223428726,-0.10365359485149384,0.05518703907728195,-0.011059150099754333,0.06586074829101562,-0.0428529717028141,0.0061818575486540794,-0.012986348010599613,-0.06993257254362106,-0.03093399479985237,0.027771415188908577,-0.021604381501674652,0.0046228040009737015,0.07183012366294861,0.035104647278785706,-0.005895248614251614,-0.008904642425477505,0.01760173961520195,-0.001713476493023336,0.04494818300008774,0.00911218672990799,0.020971864461898804,-0.048031698912382126,-0.006745192222297192,0.020714905112981796,-0.023126373067498207,0.07704837620258331,0.05301276221871376,0.08080394566059113,-0.017265714704990387,-0.00356284505687654,0.020151570439338684,-0.0015479351859539747,0.030420076