INSERT INTO `knowledge_doc` VALUES (97, '农产品地理标志保护', '法规标准', '地理标志农产品（如五常大米、赣南脐橙）指产自特定地域、品质和声誉取决于产地自然与人文因素的农产品，受《农产品地理标志管理办法》保护。假冒产地属侵权行为。消费者可查包装上的地理标志专用标志及追溯信息，扫码溯源可核对批次产地是否在标志保护范围内。', '[-0.0863814428448677,-0.009227973408997059,-0.023364847525954247,0.0020394297316670418,-0.04433232545852661,-0.045283664017915726,-0.03188883140683174,0.10380994528532028,-0.05513951927423477,0.008923545479774475,-0.061532504856586456,0.011121135205030441,-0.06796354800462723,-0.016134683042764664,0.024810880422592163,0.006901953369379044,-0.005137222353368998,-0.006654605269432068,-0.02161438763141632,-0.04901290684938431,-0.11758530884981155,-0.022679883986711502,-0.02741754613816738,0.020701102912425995,0.029110925272107124,0.00504684541374445,0.012900135479867458,0.0291870329529047,0.052361615002155304,-0.03213617950677872,-0.048327941447496414,-0.01292867586016655,2.3917217913549393E-4,-0.0026661232113838196,-0.051486384123563766,0.010274444706737995,-0.020796237513422966,0.02032056823372841,-0.07096977531909943,-0.002387857064604759,-0.017371421679854393,0.02351706102490425,-0.01984489895403385,-0.04353320226073265,0.025705138221383095,-0.033943720161914825,-0.00719686783850193,-0.029510488733649254,0.004989765118807554,-0.026808690279722214,-0.021367039531469345,-0.009403971023857594,0.09619924426078796,-0.08463098108768463,-0.0062455302104353905,0.01344239804893732,0.03649330511689186,-0.06967595219612122,-0.021861733868718147,-0.024525480344891548,-0.01930263638496399,-0.017380936071276665,-0.022736964747309685,0.014850378036499023,-0.026313994079828262,-0.0013770610094070435,0.04813767597079277,-0.03601763769984245,-0.05498730391263962,-0.022204216569662094,-0.039042890071868896,0.04650137573480606,-0.0038315115962177515,0.03257379308342934,0.00492792809382081,-0.03156537562608719,-0.010436171665787697,0.005051601678133011,0.02648523449897766,0.041706632822752,0.05110584944486618,0.026979930698871613,-0.03601763769984245,0.03082333318889141,0.022375456988811493,0.065185643